  MV.STORIES.push(
  { id: "mhc-watan", assetId: "mhc-lata-watan", title: "The Song on a Cigarette Packet",
    hook: "A poet had no paper, a singer said no, and the Prime Minister wept in front of the nation.",
    setting: "Mumbai, late 1962. India has just lost a short, bitter war with China, and the country is grieving its soldiers.",
    character: "Kavi Pradeep, a poet walking on Mahim beach, and Lata Mangeshkar, the most famous voice in India.",
    conflict: "The words came to Pradeep on the beach. He borrowed a pen from a stranger and wrote the first lines on the foil of his cigarette packet. The composer C. Ramchandra wanted a singer, but there were only weeks left before Republic Day.",
    surprise: "Lata Mangeshkar refused. There was not enough time to rehearse, and she did not want to sing badly before the Prime Minister.",
    turning: "Pradeep would not give up. He went to her again and again until she agreed. On 27 January 1963, at a Republic Day event in Delhi, she sang “Ae Mere Watan Ke Logon” for the first time.",
    payoff: "Jawaharlal Nehru wept openly. He is said to have told her that she had made him cry. The song was never put in a film, and its earnings were promised to war widows.",
    meaning: "A great work can begin with no paper and almost no time. What it needs is someone who refuses to let it die.",
    extra: ["Pradeep was not invited to the Delhi event and only sang the song for Nehru two months later at a school in Mumbai.", "Asha Bhosle was first chosen to sing it and even rehearsed, but withdrew before the Delhi trip.", "Some accounts give the date as 26 January, others 27 January 1963."],
    facts: [["1962", "china"], ["cigarette", "mahim"], ["pradeep"], ["lata"], ["refused", "said no"], ["1963", "republic day"], ["nehru", "wept", "cry"]],
    vocab: ["grieving", "rehearse", "refuse"] },

  { id: "mhc-anandwan", assetId: "mhc-baba-amte", title: "The Man in the Rain",
    hook: "A rich lawyer ran away from a dying man in the rain. Then he spent his life making up for it.",
    setting: "Warora, a small town in Chandrapur district, in the 1940s. Murlidhar Devidas Amte is a wealthy young lawyer with a fast car and fine clothes.",
    character: "Baba Amte, proud and brave, who had already given up his law practice to work with sweepers, and his wife Sadhana.",
    conflict: "One rainy night he saw a man with advanced leprosy lying in a gutter, fingers gone, close to death. Amte, who feared nothing, ran away in fear.",
    surprise: "The shame of that fear would not leave him. He went back, carried the man home and fed him until he died. Then he trained himself in leprosy care and let doctors inject him with bacteria from a patient, to prove the disease did not spread easily.",
    turning: "On 15 August 1949, with his wife, a few patients and almost no money, he began Anandwan, the Forest of Joy, on rocky land near Warora. Patients cleared the land themselves.",
    payoff: "Anandwan grew into a village of thousands with farms, workshops, schools and a hospital, paid for by the work of its own people. Amte received the Magsaysay Award in 1985.",
    meaning: "Fear points at the work you must do. Dignity through work heals more than pity ever can.",
    extra: ["He took the name Baba, meaning father, from the people he served.", "His sons Vikas and Prakash both became doctors and carried the work to new places, including Hemalkasa.", "In his old age he lived for years beside the Narmada river in protest against big dams."],
    facts: [["rain", "gutter"], ["leprosy"], ["fear", "ran away"], ["inject", "bacteria"], ["1949"], ["anandwan", "forest of joy"], ["work", "workshop"]],
    vocab: ["shame", "dignity", "self-supporting"] },

  { id: "mhc-hiware", assetId: "mhc-hiware-bazar", title: "The Village That Budgets Its Rain",
    hook: "A village with almost no rain and no hope sent for its only educated son. He asked them to count water like money.",
    setting: "Hiware Bazar, Ahmednagar district, 1989. Rain is about 400 mm a year. Only about 12% of the land can grow anything, and there are more liquor shops than wells with water.",
    character: "Popatrao Pawar, the only postgraduate the village had produced, who wanted to be a cricketer in Mumbai.",
    conflict: "Families were leaving for the cities. The elders asked Pawar to come back and stand for sarpanch. His own family was against it.",
    surprise: "He agreed, and the first thing he did was close every liquor shop and ban tobacco. People were angry. But he argued that a village that drank could not save water.",
    turning: "With free labour, the village built dozens of earthen and stone bunds, check dams and percolation tanks. Rain that used to run off now soaked into the ground. Then came the strange rule: every year after the monsoon, the village measures its water and plans its crops to fit. No sugarcane, no bore wells for irrigation.",
    payoff: "Wells filled. Milk production rose many times over. Families who had left came back, and Hiware Bazar became known as a village of lakhpati farmers. Pawar later led Maharashtra's model-village programme.",
    meaning: "You cannot spend what you have not counted. A budget for water saved a village that a budget for money could not.",
    extra: ["Per-person income rose from about 830 rupees a month in 1995 to around 30,000 rupees by the 2010s, by Down to Earth's reporting.", "Free grazing was banned too, so grass and trees came back and held the soil.", "The village gets the same rain it always did. Only the habits changed."],
    facts: [["1989"], ["400"], ["pawar", "sarpanch"], ["liquor"], ["bund", "check dam", "percolation"], ["measure", "budget"], ["sugarcane", "bore"]],
    vocab: ["budget", "watershed", "percolation"] });

